INSERT INTO erp_solutions (legacy_id, name, type, tagline, description, features, image_url, consultation, sort_order, created_at, updated_at) VALUES ('6a7241db0f7686103f060d56', 'ERPNext', 'ERPNext', 'Open-source, full-stack ERP', 'A modern, open-source ERP covering accounting, inventory, HR, manufacturing and CRM. Rapid to deploy and infinitely customizable — ideal for growing businesses across emerging markets.', '["Accounting & VAT compliance","Inventory & warehouse","HR & payroll","Manufacturing","CRM module","Multi-currency"]', '/uploads/migrated/c025c9c36_generated_image.png', 1, 1, '2026-08-04 19:47:39', '2026-08-04 20:19:54');
INSERT INTO erp_solutions (legacy_id, name, type, tagline, description, features, image_url, consultation, sort_order, created_at, updated_at) VALUES ('6a7241db0f7686103f060d57', 'Odoo', 'Odoo', 'Modular business apps suite', 'A suite of integrated business applications — from CRM and accounting to e-commerce and manufacturing — with thousands of modules. We implement, customize and host Odoo end-to-end.', '["Modular apps ecosystem","CRM & sales","Accounting","E-commerce","Custom module development","Cloud or on-premise"]', '/uploads/migrated/49dfe4b45_generated_image.png', 1, 2, '2026-08-04 19:47:39', '2026-08-04 20:19:54');
INSERT INTO erp_solutions (legacy_id, name, type, tagline, description, features, image_url, consultation, sort_order, created_at, updated_at) VALUES ('6a7241db0f7686103f060d58', 'Custom CRM', 'Custom CRM', 'Built around your pipeline', 'When off-the-shelf CRMs don''t fit your sales motion, we engineer a custom CRM tailored to your pipeline, automation rules and reporting — integrated with your existing stack.', '["Tailored sales pipelines","Workflow automation","Custom reporting","Third-party integrations","Role-based access","Mobile-ready"]', '/uploads/migrated/b03afa878_generated_image.png', 1, 3, '2026-08-04 19:47:39', '2026-08-04 20:19:54');
INSERT INTO erp_solutions (legacy_id, name, type, tagline, description, features, image_url, consultation, sort_order, created_at, updated_at) VALUES ('6a7241db0f7686103f060d59', 'Custom ERP', 'Custom ERP', 'Engineered for your operations', 'Bespoke ERP systems built from the ground up for industries with specialized workflows — manufacturing, logistics, retail chains and multi-entity enterprises.', '["Domain-specific workflows","Multi-entity consolidation","Custom approvals engine","BI & dashboards","API-first architecture","Hardware integration"]', '/uploads/migrated/c41a53314_generated_image.png', 1, 4, '2026-08-04 19:47:39', '2026-08-04 20:19:54');
