INSERT INTO projects (legacy_id, title, client, region, year, description, image_url, tech_stack, url, featured, created_at, updated_at) VALUES ('6a725920304c5a36dbca31db', 'ERPNext Enterprise Management System for UAE Based Company', 'UAE-Based Company', 'UAE', 'Jan 2026 - Mar 2026', 'Designed and implemented a full-scale ERPNext enterprise solution for a UAE-based company to automate and centralize business operations. End-to-end ERP covering Finance & Accounting (with optional AI-based insights), HRMS, UAE-compliant Payroll Automation, Procurement & Inventory Management, CRM & Sales Pipeline, Asset Management (10,000+ items) and Project Management. Included data migration from the legacy system.', NULL, '["ERPNext","Frappe","Python","MariaDB"]', NULL, 1, '2026-08-04 21:26:56', '2026-08-04 21:26:56');
